// Outward offset for the clockwise M/L/H/C/Z paths generated by this demo.
// Evaluate cubic positions and tangents directly; no browser geometry queries.
// Straight segments need only their endpoints. Curves use a derivative bound
// to keep samples at most 0.25px apart along the original curve.
export function offsetFocusPath(path, distance) {
  const tokens = path.match(/[MLHCZ]|-?\d*\.?\d+(?:e[-+]?\d+)?/gi);
  let index = 0,
    current,
    start;
  const points = [];
  const number = () => Number(tokens[index++]);
  const point = () => [number(), number()];
  const offset = (p, dx, dy) => {
    const speed = Math.hypot(dx, dy);
    if (speed < 1e-9) return;
    points.push([p[0] + (distance * dy) / speed, p[1] - (distance * dx) / speed]);
  };
  const line = (end) => {
    const dx = end[0] - current[0],
      dy = end[1] - current[1];
    offset(current, dx, dy);
    offset(end, dx, dy);
    current = end;
  };
  while (index < tokens.length) {
    const command = tokens[index++];
    if (command === 'M') {
      current = point();
      start = current;
    } else if (command === 'L') line(point());
    else if (command === 'H') line([number(), current[1]]);
    else if (command === 'Z') line(start);
    else if (command === 'C') {
      const a = current,
        b = point(),
        c = point(),
        d = point();
      const edges = [
        [b[0] - a[0], b[1] - a[1]],
        [c[0] - b[0], c[1] - b[1]],
        [d[0] - c[0], d[1] - c[1]],
      ];
      const steps = Math.max(
        1,
        Math.ceil((3 * Math.max(...edges.map(([x, y]) => Math.hypot(x, y)))) / 0.25),
      );
      for (let step = 0; step <= steps; step++) {
        const t = step / steps,
          u = 1 - t;
        const p = [0, 1].map(
          (axis) =>
            u * u * u * a[axis] +
            3 * u * u * t * b[axis] +
            3 * u * t * t * c[axis] +
            t * t * t * d[axis],
        );
        const tangent = [0, 1].map(
          (axis) =>
            3 * (u * u * edges[0][axis] + 2 * u * t * edges[1][axis] + t * t * edges[2][axis]),
        );
        offset(p, tangent[0], tangent[1]);
      }
      current = d;
    } else throw new Error(`Unsupported focus-path command: ${command}`);
  }
  return (
    points.map(([x, y], i) => `${i ? 'L' : 'M'} ${x.toFixed(4)} ${y.toFixed(4)}`).join(' ') + ' Z'
  );
}
